import{z as E,x as A,o as n,c as d,q as i,j as s,D as e,d as t,s as m,S as r,b as l}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"FlashAttention 重读：tiling 与 online softmax","description":"","frontmatter":{"title":"FlashAttention 重读：tiling 与 online softmax","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ak-flashattention-reread.md","filePath":"llm/ak-flashattention-reread.md","lastUpdated":1791413859000}'),B={name:"llm/ak-flashattention-reread.md"};function f(h,a,p,x,C,D){const o=A("Mermaid");return n(),d("div",null,[a[2]||(a[2]=i('<h1 id="flashattention-重读-tiling-与-online-softmax" tabindex="-1">FlashAttention 重读：tiling 与 online softmax <a class="header-anchor" href="#flashattention-重读-tiling-与-online-softmax" aria-label="Permalink to &quot;FlashAttention 重读：tiling 与 online softmax&quot;">​</a></h1><div class="epigraph"><p>FlashAttention 的贡献不在算得少，而在把中间结果钉在片上存储里；tiling 决定搬什么，online softmax 决定算到一半怎么办。</p><footer>—— 据 Dao et al., FlashAttention, 2022 整理</footer></div><p><a href="/llm/sgt-map">上一课</a>把自博弈深化的边界与收束写完，后训练与自训练一族到这里告一段落。本课是「注意力内核工程」的第一课，部署研究从推理热路径上跑得最多的那个内核讲起。本栏里你已经读过 <a href="/llm/sdpa">SDPA</a> 的公式与 <a href="/llm/flashattention">FlashAttention</a> 的定位：不物化 \\(n\\times n\\) 分数矩阵、计算仍是精确注意力、收益主要来自省 HBM 流量。本课重读它，问的是内核作者的问题：这两条性质靠什么写出来——答案是 tiling 与 online softmax 这一对配套件。后课的访存分析、片上预算、各路变体与移植，都默认你已能把这对件装进脑子。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>会算注意力与会写注意力内核之间隔着什么。标准实现要走三趟：\\(S=QK^\\top\\) 把 \\(n\\times n\\) 的分数写进 HBM，softmax 再把它读出来改写回去，\\(O=PV\\) 第三遍读它。\\(n=8192\\)、单头、fp16 时，光这张矩阵就是 \\(128\\,\\mathrm{MiB}\\)，在显存里滚三个来回。缺口因此不是 FLOPs，而是：能不能让它根本不落显存。障碍有两个。其一，softmax 的分母要扫完整行才知道，而分块之后每一行只看到一部分键。其二，直接分块会把「归一化」这个全局操作切碎，切错顺序数值就崩。</p><p><span class="marginnote">直觉类比：标准实现像做菜要三次进出冷库——半成品切好放回去，取出来调味再放回去，再取出来装盘。FlashAttention 是把灶台搬到手上（片上 SRAM）：食材切一块炒一块，装盘前根本不进冷库。菜没变（还是精确注意力），变的是中间成品不再来回搬运。</span></p><h3 id="softmax-不能分块算——直到随身带上统计量" tabindex="-1">softmax 不能分块算——直到随身带上统计量 <a class="header-anchor" href="#softmax-不能分块算——直到随身带上统计量" aria-label="Permalink to &quot;softmax 不能分块算——直到随身带上统计量&quot;">​</a></h3><p>softmax 逐行定义：减最大值、取指数、除以行和。最大值与行和都是行内归约量，看全行之前只有部分结果。若先对每个块局部 softmax 再把结果平均，得到的是另一个函数，不是 softmax——归一化不是可分的局部操作。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>tiling 把 \\(Q\\) 切成 \\(B_r\\times d\\) 的行块，\\(K,V\\) 切成 \\(B_c\\times d\\) 的列块；外层循环扫 KV 块，逐块载入片上 SRAM，内层在片上算这个块的 \\(S\\)。online softmax 给每行随身维护三个量：运行最大值 \\(m\\)、运行和 \\(l\\)、未归一化输出 \\(O\\)。新块带来分数 \\(S\\)，先更新 \\(m&#39;=\\max(m,\\ \\mathrm{rowmax}(S))\\)，再把旧结果按 \\(e^{m-m&#39;}\\) 重缩放：</p> \\[O \\leftarrow e^{m-m&#39;}O + e^{S-m&#39;}V,\\qquad l \\leftarrow e^{m-m&#39;}l + \\mathrm{rowsum}\\left(e^{S-m&#39;}\\right),\\qquad m \\leftarrow m&#39;. \\]<p>KV 块扫完之后 \\(O \\leftarrow O/l\\)，一次归一化收尾。每一步只依赖已见过的块，顺序无关。</p><p><span class="marginnote">术语翻译：online softmax 就是「边收卷子边记统计」——不等全部分数到齐才求最大值与总和，每来一块，就用新最大值把已积累的结果按比例修正一遍，收完最后一块再统一除一次行和。名字里的 online 指的就是这种来一块处理一块的流式做法。</span></p>',13)),(n(),s(r,null,{default:e(()=>[m(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20QIN%5B%22Q%20%E8%A1%8C%E5%9D%97%E9%A9%BB%E7%95%99%E7%89%87%E4%B8%8A%22%5D%20--%3E%20S%5B%22%E7%89%87%E4%B8%8A%E7%AE%97%20S%20%3D%20Q%20K%5ET%22%5D%0A%20%20KVIN%5B%22%E5%A4%96%E5%B1%82%EF%BC%9A%E8%BD%BD%E5%85%A5%20K%2CV%20%E5%9D%97%E5%88%B0%20SRAM%22%5D%20--%3E%20S%0A%20%20S%20--%3E%20UP%5B%22%E6%9B%B4%E6%96%B0%20m%E2%80%B2%E3%80%81l%E3%80%81O%EF%BC%9A%E9%87%8D%E7%BC%A9%E6%94%BE%E7%B4%AF%E5%8A%A0%22%5D%0A%20%20UP%20--%3E%20MORE%7B%22%E8%BF%98%E6%9C%89%20KV%20%E5%9D%97%3F%22%7D%0A%20%20MORE%20--%3E%7C%E6%98%AF%7C%20KVIN%0A%20%20MORE%20--%3E%7C%E5%90%A6%7C%20NORM%5B%22O%20%E2%86%90%20O%20%2F%20l%EF%BC%8C%E5%86%99%E5%9B%9E%20HBM%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[t("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,[t("为什么这样合并是对的：每行的部分结果构成三元组 \\((m,l,O)\\)，而 \\((m,l,O)\\) 上的合并满足结合律——两个部分用 \\(\\max\\) 并最大值、按指数加权并和与输出。这条结合律是精确的，不是近似，后面长序列切分与 "),l("a",{href:"/llm/flashdecoding"},"FlashDecoding"),t(" 的二层归并用的正是它。减最大值还兼任数值保险：\\(e^{S-m'}\\) 保证指数不上溢。不这么做错在哪：想省一趟就把局部 softmax 的结果落盘再平均，分布已经错了；或者干脆先算 \\(P\\) 再乘 \\(V\\)，\\(n\\times n\\) 回到显存，等于没写。")],-1)),(n(),s(r,null,{default:e(()=>[m(o,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E5%9D%97%201%20%E7%9A%84%E9%83%A8%E5%88%86%E7%BB%93%E6%9E%9C%20m1%2C%20l1%2C%20O1%22%5D%20--%3E%20MG%5B%22%E5%90%88%E5%B9%B6%3A%20m%20%3D%20max(m1%2C%20m2)%22%5D%0A%20%20B%5B%22%E5%9D%97%202%20%E7%9A%84%E9%83%A8%E5%88%86%E7%BB%93%E6%9E%9C%20m2%2C%20l2%2C%20O2%22%5D%20--%3E%20MG%0A%20%20MG%20--%3E%20R1%5B%22O%20%E6%8C%89%E6%8C%87%E6%95%B0%E5%8A%A0%E6%9D%83%3A%20%E4%B8%A4%E5%9D%97%E5%90%84%E4%B9%98%20e%20%E7%9A%84%E5%B7%AE%E5%80%BC%22%5D%0A%20%20MG%20--%3E%20R2%5B%22l%20%E5%90%8C%E6%A0%B7%E5%8A%A0%E6%9D%83%E7%9B%B8%E5%8A%A0%22%5D%0A%20%20R1%20--%3E%20OUT%5B%22%E4%B8%8E%E4%B8%80%E6%AC%A1%E6%80%A7%E7%AE%97%E5%85%A8%E8%A1%8C%2C%20%E7%BB%93%E6%9E%9C%E5%AE%8C%E5%85%A8%E7%9B%B8%E5%90%8C%22%5D%0A%20%20R2%20--%3E%20OUT%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p>成本账要按字节记。FlashAttention 论文的口径：标准实现需要 \\(O(n^2)\\) 量级的额外 HBM 读写（\\(S\\) 与 \\(P\\) 各进出一遍），FlashAttention 把它降到 \\(O(n^2 d^2/M)\\)，其中 \\(M\\) 是片上 SRAM 容量——\\(d\\) 固定、\\(M\\) 以百 KB 计时，主项被 tile 大小吃掉。SRAM 比 HBM 快一个数量级，这就是「省字节」能兑换成时间的原因，下一课把这本账展开。</p><p><span class="marginnote">\\(n=8192\\)、\\(d=128\\)、fp16：一张 \\(S\\) 矩阵 \\(128\\,\\mathrm{MiB}\\)。A100 上 HBM 约 \\(1.5\\)–\\(2\\,\\mathrm{TB/s}\\)，SRAM 约 \\(19\\,\\mathrm{TB/s}\\)——\\(S\\) 每少走一个来回，就省下零点一毫秒量级的搬运。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>FLOPs 一个没少，省的全是字节；渐近计算仍对 \\(n\\) 二次，二次项本身要靠稀疏或线性变体去动，那是本课程后面的事。训练要反向：分数矩阵没存，就用重算把前向再走一遍换掉存储，数学对象仍是同一个 Jacobian，见<a href="/llm/attention-backward">注意力的反向传播</a>。因果掩码在块内逐元素施加，对角块之外的整块直接跳过，白送一份稀疏。dropout 同样是块内的逐元素操作。解码时查询只有一两行，沿查询维并行失效，要沿 KV 维另想办法，本课程到长序列一课再收。</p><p><span class="marginnote">初学者容易以为「分数矩阵没存，反向就没法算了」——实际上训练时用重算把前向再走一遍，把需要的中间量当场重新造出来，用一点计算时间换显存。求的还是同一个导数，只是不把它留到反向那一步。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>tiling 与 online softmax 是一对配套件：前者定搬运粒度，后者让归一化可以边算边改。</li><li>online softmax 的本质是每行随身带 \\((m,l,O)\\) 三个统计量，合并满足结合律，精确无近似。</li><li>省的是 HBM 流量，不是 FLOPs；访存量从 \\(O(n^2)\\) 降到 \\(O(n^2 d^2/M)\\)。</li><li>因果掩码、dropout 都落在块内；对角块外的整块跳过是免费的稀疏。</li><li>解码与长序列要换并行轴，不是这套骨架失效。</li><li>出处：Dao et al., <em>FlashAttention</em>, NeurIPS 2022；online softmax 归约见 Milakov &amp; Gimelshein, 2018。</li></ul>',7))])}const u=E(B,[["render",f]]);export{c as __pageData,u as default};
